import{b as s,O as a,g as t,j as e}from"./chunks/framework.DcaUmd3X.js";const r=JSON.parse('{"title":"创建版本库","description":"","frontmatter":{},"headers":[],"relativePath":"git/basics/init-repo/index.md","filePath":"Git操作手册/2.基础操作/01.创建版本库.md","lastUpdated":1781394803000}'),h={name:"git/basics/init-repo/index.md"};function n(l,i,p,d,o,k){return a(),t("div",null,[...i[0]||(i[0]=[e(`<h1 id="创建版本库" tabindex="-1">创建版本库 <a class="header-anchor" href="#创建版本库" aria-label="Permalink to &quot;创建版本库&quot;">​</a></h1><blockquote><p>两种方式把代码搞到 GitHub 上：本地已有项目 or 从零拉取</p></blockquote><h2 id="什么是版本库" tabindex="-1">什么是版本库 <a class="header-anchor" href="#什么是版本库" aria-label="Permalink to &quot;什么是版本库&quot;">​</a></h2><p>版本库（Repository，简称 repo）就是 Git 管理的那个目录。Git 会在这个目录里建一个隐藏的 <code>.git</code> 文件夹，里面存着所有的版本历史、分支、配置——仓库的&quot;灵魂&quot;全在里面。</p><p>删掉 <code>.git</code> 文件夹，这个目录就退化成普通文件夹，版本历史全部丢失。</p><h2 id="第一步-在-github-上创建仓库" tabindex="-1">第一步：在 GitHub 上创建仓库 <a class="header-anchor" href="#第一步-在-github-上创建仓库" aria-label="Permalink to &quot;第一步：在 GitHub 上创建仓库&quot;">​</a></h2><p>无论哪种方式，先在 GitHub 上建一个空仓库——它是本地代码的&quot;远程家&quot;。</p><p>登录 GitHub → 右上角 <code>+</code> → New repository → 填仓库名 → <strong>不要勾选 README 和 .gitignore</strong>（空仓库就行）→ Create repository。</p><p>GitHub 会跳转到一个快速设置页面，下面两种方式任选一种。</p><h2 id="方式一-本地已有项目-推到-github" tabindex="-1">方式一：本地已有项目，推到 GitHub <a class="header-anchor" href="#方式一-本地已有项目-推到-github" aria-label="Permalink to &quot;方式一：本地已有项目，推到 GitHub&quot;">​</a></h2><p>适用场景：你已经有一个项目文件夹，想把代码纳入 Git 管理并推到 GitHub。</p><h3 id="_1-初始化本地仓库" tabindex="-1">1. 初始化本地仓库 <a class="header-anchor" href="#_1-初始化本地仓库" aria-label="Permalink to &quot;1. 初始化本地仓库&quot;">​</a></h3><p>进入项目目录，执行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span></span></code></pre></div><p>这个命令只做一件事：在当前目录创建一个 <code>.git</code> 隐藏文件夹。此时这个目录就变成了 Git 仓库——但目前还只是空壳，Git 还没开始跟踪任何文件。</p><h3 id="_2-看看仓库状态" tabindex="-1">2. 看看仓库状态 <a class="header-anchor" href="#_2-看看仓库状态" aria-label="Permalink to &quot;2. 看看仓库状态&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span></code></pre></div><p>输出会列出 <code>Untracked files</code>——你目录里的文件 Git 还没开始跟踪。</p><h3 id="_3-把文件加入暂存区" tabindex="-1">3. 把文件加入暂存区 <a class="header-anchor" href="#_3-把文件加入暂存区" aria-label="Permalink to &quot;3. 把文件加入暂存区&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 添加所有文件</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span></code></pre></div><p><code>git add .</code> 把当前目录下所有文件加入暂存区。再敲 <code>git status</code>，文件从 <code>Untracked</code> 变成了 <code>Changes to be committed</code>——准备好了。</p><h3 id="_4-提交" tabindex="-1">4. 提交 <a class="header-anchor" href="#_4-提交" aria-label="Permalink to &quot;4. 提交&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> commit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;第一次提交，搭建项目骨架&quot;</span></span></code></pre></div><p><code>-m</code> 后面跟提交信息，描述这次改了什么。从此这个快照永久存入 Git 历史。</p><h3 id="_5-关联远程仓库并推送" tabindex="-1">5. 关联远程仓库并推送 <a class="header-anchor" href="#_5-关联远程仓库并推送" aria-label="Permalink to &quot;5. 关联远程仓库并推送&quot;">​</a></h3><p>回到 GitHub 刚才建仓库的页面，会看到一段快速设置指引。复制 SSH 地址（以 <code>git@github.com:</code> 开头的那一串），然后回到终端：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> remote</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> git@github.com:你的用户名/仓库名.git</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> branch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -M</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> master</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> master</span></span></code></pre></div><p>一行一行敲：</p><ul><li><code>git remote add origin &lt;地址&gt;</code> — 把 GitHub 仓库地址关联到本地，起名叫 <code>origin</code>（约定俗成，看到 origin 就知道是远程仓库）</li><li><code>git branch -M master</code> — 把本地主分支统一命名为 <code>master</code></li><li><code>git push -u origin master</code> — 把本地代码推到 GitHub，<code>-u</code> 让本地和远程建立&quot;追踪&quot;，以后直接敲 <code>git push</code> 就行</li></ul><p>刷一下 GitHub 页面，代码已经在上面了。</p><h2 id="方式二-没有本地项目-从-github-拉取" tabindex="-1">方式二：没有本地项目，从 GitHub 拉取 <a class="header-anchor" href="#方式二-没有本地项目-从-github-拉取" aria-label="Permalink to &quot;方式二：没有本地项目，从 GitHub 拉取&quot;">​</a></h2><p>适用场景：你要参与一个已有的项目，或者想在另一台电脑上继续开发。</p><p>在 GitHub 仓库页面找到绿色的 Code 按钮 → 点开 → 选 SSH → 复制地址，然后在终端执行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> git@github.com:用户名/仓库名.git</span></span></code></pre></div><p>这条命令做了三件事：</p><ol><li>在当前目录下建一个和仓库同名的文件夹</li><li>把远程仓库的所有文件、提交历史、分支全部下载下来</li><li>自动关联好远程仓库（不需要再手动 <code>git remote add</code>）</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 克隆并指定文件夹名</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> git@github.com:用户名/仓库名.git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 我的项目</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 进去开始干活</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 我的项目</span></span></code></pre></div><blockquote><p>💡 想给克隆下来的文件夹换个名字？在命令后面加上就行。克隆完记得 <code>cd</code> 进目录——新手最容易忘的一步。</p></blockquote><h2 id="后续提交-commit-am" tabindex="-1">后续提交：commit -am <a class="header-anchor" href="#后续提交-commit-am" aria-label="Permalink to &quot;后续提交：commit -am&quot;">​</a></h2><p>第一次提交之后，改了几个已有文件，不想分两步？一步到位：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> commit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -am</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;修复了首页样式问题&quot;</span></span></code></pre></div><p><code>-a</code> 自动把所有<strong>已跟踪</strong>文件的修改加入暂存区并提交。注意——新建的文件不会被包含，新文件还是得先 <code>git add</code>。</p><h2 id="提交信息怎么写" tabindex="-1">提交信息怎么写 <a class="header-anchor" href="#提交信息怎么写" aria-label="Permalink to &quot;提交信息怎么写&quot;">​</a></h2><p>提交信息是给自己和同事看的备忘录。三个月后你翻 git log，全靠它回忆当时改了啥：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ❌ 没用的提交信息</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> commit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;fix&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> commit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;修改&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> commit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;update&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ✅ 一看就知道改了什么</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> commit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;修复首页导航栏在移动端错位的问题&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> commit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;给用户列表接口加上分页参数&quot;</span></span></code></pre></div><p>原则：<strong>一读就懂，不用翻代码</strong>。后面会讲约定式提交（feat/fix/docs），让提交信息更规范。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>这章走完了两条路径，最终都通往同一个目的地：</p><table tabindex="0"><thead><tr><th></th><th>适用场景</th><th>核心命令</th></tr></thead><tbody><tr><td>方式一</td><td>本地已有项目</td><td><code>init</code> → <code>add</code> → <code>commit</code> → <code>remote add</code> → <code>push</code></td></tr><tr><td>方式二</td><td>从零参与项目</td><td><code>clone</code>，一步到位</td></tr></tbody></table><p>记住日常节奏：<strong>改代码 → add → commit → push</strong>。每天来来回回就这四个动作。</p><h2 id="自主练习" tabindex="-1">自主练习 <a class="header-anchor" href="#自主练习" aria-label="Permalink to &quot;自主练习&quot;">​</a></h2><ol><li>在 GitHub 新建一个空仓库，把本地项目用方式一推上去，确认文件出现在 GitHub</li><li>换个目录，用 <code>git clone</code> 把刚才的仓库拉下来，确认文件和历史都在</li><li>在克隆下来的仓库里改一个文件，用 <code>commit -am</code> 提交并推送</li></ol>`,52)])])}const g=s(h,[["render",n]]);export{r as __pageData,g as default};
